pytestmark = pytest.mark.skipif(
    not run_test_for_class(TimeH2OForecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)

# All tests use the same loading arguments, so they share one cached model.
_RTOL = 1e-5
_ATOL = 1e-4


def _assert_matches(actual, expected):
    np.testing.assert_allclose(
        np.asarray(actual, dtype=np.float64).ravel(),
        np.asarray(expected, dtype=np.float32),
        rtol=_RTOL,
        atol=_ATOL,
    )


@pytest.fixture(scope="module")
def fitted_airline():
    """Default forecaster fitted once on the airline series."""
    return TimeH2OForecaster(model_path=None, device="cpu").fit(load_airline())


_UNIVARIATE_CASES = [
    pytest.param(
        "predict",
        {"fh": [1, 2, 3]},
        [434.6744689941406, 437.6665344238281, 443.0233154296875],
        id="point",
    ),
    pytest.param(
        "predict",
        {"fh": [2, 4, 6]},
        [437.66650390625, 441.17657470703125, 437.4513244628906],
        id="sparse_fh",
    ),
    pytest.param(
        "predict_quantiles",
        {"fh": [1], "alpha": [0.05, 0.25, 0.9]},
        [305.05657958984375, 415.40667724609375, 535.0983276367188],
        id="quantiles",
    ),
]


@pytest.mark.parametrize("method,kwargs,expected", _UNIVARIATE_CASES)
def test_timeh2o_univariate_matches_reference(fitted_airline, method, kwargs, expected):
    """Point and quantile forecasts match raw h2ofm."""
    _assert_matches(getattr(fitted_airline, method)(**kwargs), expected)


def test_timeh2o_predict_proba_matches_reference(fitted_airline):
    """The distribution reproduces h2ofm's native quantiles at the grid levels."""
    pytest.importorskip("skpro")
    dist = fitted_airline.predict_proba(fh=[1])
    _assert_matches(
        [dist.ppf(p).to_numpy() for p in [0.1, 0.5, 0.9]],
        [333.685546875, 434.6744689941406, 535.0983276367188],
    )


def test_timeh2o_forecast_kwargs_match_reference():
    """Options in ``forecast_kwargs`` are forwarded to h2ofm."""
    forecaster = TimeH2OForecaster(
        model_path=None,
        device="cpu",
        forecast_kwargs={
            "context_length": 16,
            "flip_equivariant": False,
            "clip_nonnegative": True,
        },
    )
    y_pred = forecaster.fit(load_airline()).predict(fh=[1, 2, 3])
    _assert_matches(y_pred, [457.5307312011719, 480.4246826171875, 439.52996826171875])


def test_timeh2o_multivariate_covariates_match_reference():
    """Multiple targets with numeric and categorical future covariates."""
    y = load_airline()
    y = pd.DataFrame({"a": y, "b": y / 10})
    index = y.index.append(pd.period_range(y.index[-1] + 1, periods=2, freq="M"))
    month = np.arange(len(index)) % 12
    quarter = pd.Categorical([f"q{m // 3}" for m in month])
    X_all = pd.DataFrame({"month": month + 1.0, "quarter": quarter}, index=index)
    X, X_future = X_all.iloc[: len(y)], X_all.iloc[len(y) :]

    forecaster = TimeH2OForecaster(model_path=None, device="cpu")
    y_pred = forecaster.fit(y, X=X).predict(fh=[1, 2], X=X_future)
    _assert_matches(
        y_pred,
        [439.7320251464844, 43.973201751708984, 439.91748046875, 43.99174880981445],
    )
